  OPTIONAL { ?p ref:hasTimeseriesId ?ts . }
} LIMIT 50

SELECT ?point ?uri ?label ?ts WHERE {
  ?dev brick:hasPoint ?point .
  ?point rdf:type ?t .
  FILTER (CONTAINS(STR(?t), "Power"))
  ?dev ?lbl ?l2 .
  FILTER (regex(str(?dev), "AHU01|CondPump02|HWPump01"))
  OPTIONAL { ?point ref:hasExternalReference ?uri . ?uri ref:hasTimeseriesId ?ts . }
